import * as THREE from 'three';

const clamp = (v, min, max) => Math.min(max, Math.max(min, v));

// Rotor corners in X configuration. Index pairs (0,2) and (1,3) are diagonal,
// so spin directions alternate around the frame: +,-,+,-.
const CORNERS = [
  { x: 1, z: 1 },
  { x: 1, z: -1 },
  { x: -1, z: -1 },
  { x: -1, z: 1 },
];

/**
 * Build a quadcopter drone.
 *
 * Hierarchy:
 *   root
 *   ├── body (Group)          <- pitched/rolled by updateDrone, holds body box
 *   │     └── body box mesh
 *   └── arms x4 (X layout)    <- hold the rotor Groups at their tips
 *         └── rotor-N (Group)
 *               └── 2 blade boxes
 *
 * Arms are parented to the root (not the banking body) so the rotor hubs keep
 * their horizontal standoff of `armLen` from the body center regardless of bank.
 *
 * @param {{armLen?: number}} [opts]
 */
export function buildDrone({ armLen = 2 } = {}) {
  const root = new THREE.Group();
  root.name = 'drone';

  // --- Body ---
  const body = new THREE.Group();
  body.name = 'body';
  const bodyBox = new THREE.Mesh(
    new THREE.BoxGeometry(0.5, 0.22, 0.7),
    new THREE.MeshStandardMaterial({ color: 0x222831 })
  );
  bodyBox.name = 'body-box';
  body.add(bodyBox);
  root.add(body);

  // --- Arms in an X, with a rotor Group at each tip ---
  const half = armLen / Math.SQRT2; // diagonal offset so tips sit armLen away
  const rotors = [];

  for (let i = 0; i < 4; i++) {
    const { x: cx, z: cz } = CORNERS[i];
    const dirX = cx / Math.SQRT2;
    const dirZ = cz / Math.SQRT2;

    // Arm box from body center out to the tip.
    const arm = new THREE.Group();
    arm.name = `arm-${i}`;
    const armMesh = new THREE.Mesh(
      new THREE.BoxGeometry(armLen, 0.08, 0.08),
      new THREE.MeshStandardMaterial({ color: 0x393e46 })
    );
    // Box is centered on its own origin; shift it outward along its length.
    armMesh.position.x = armLen / 2;
    armMesh.rotation.y = Math.atan2(-dirZ, dirX);
    arm.add(armMesh);
    root.add(arm);

    // Rotor hub at the arm tip; blades are children so they spin with it.
    const rotor = new THREE.Group();
    rotor.name = `rotor-${i}`;
    rotor.position.set(cx * half, 0.09, cz * half);
    rotor.userData.dir = i % 2 === 0 ? 1 : -1; // diagonals match, neighbors oppose

    const bladeGeo = new THREE.BoxGeometry(armLen * 0.45, 0.02, 0.14);
    const bladeMat = new THREE.MeshStandardMaterial({ color: 0x00adb5 });
    for (const side of [1, -1]) {
      const blade = new THREE.Mesh(bladeGeo, bladeMat);
      blade.position.x = side * (armLen * 0.45) / 2;
      rotor.add(blade);
    }

    arm.add(rotor);
    rotors.push(rotor);
  }

  return { root, body, rotors };
}

/**
 * Advance rotor spin and apply bank-into-motion tilt.
 *
 * @param {{body: THREE.Group, rotors: THREE.Group[]}} d  drone from buildDrone
 * @param {number} dt        delta time in seconds
 * @param {{x:number, y:number, z:number}} velocity  velocity vector
 */
export function updateDrone(d, dt, velocity) {
  for (const rotor of d.rotors) {
    rotor.rotation.y += rotor.userData.dir * 40 * dt;
  }
  // Bank into motion: pitch follows forward/backward speed, roll follows strafe.
  d.body.rotation.x = clamp(-0.3 * velocity.z, -0.4, 0.4);
  d.body.rotation.z = clamp(0.3 * velocity.x, -0.4, 0.4);
}

