import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildDrone, updateDrone } from '../src/drone.js';

function worldPos(obj) {
  return obj.getWorldPosition(new THREE.Vector3());
}

function horizontalDistance(obj) {
  const p = worldPos(obj);
  return Math.hypot(p.x, p.z);
}

describe('quadcopter drone', () => {
  it('advances rotor pairs +20/-20 rad after dt=0.5 with zero velocity', () => {
    const d = buildDrone();
    updateDrone(d, 0.5, { x: 0, y: 0, z: 0 });

    expect(d.rotors[0].rotation.y).toBeCloseTo(20, 9);
    expect(d.rotors[2].rotation.y).toBeCloseTo(20, 9);
    expect(d.rotors[1].rotation.y).toBeCloseTo(-20, 9);
    expect(d.rotors[3].rotation.y).toBeCloseTo(-20, 9);
  });

  it('diagonal rotors share sign and adjacent rotors oppose', () => {
    const d = buildDrone();
    updateDrone(d, 0.25, { x: 0, y: 0, z: 0 });

    const signs = d.rotors.map((r) => Math.sign(r.rotation.y));
    // Diagonal pairs match: (0,2) and (1,3)
    expect(signs[0]).toBe(signs[2]);
    expect(signs[1]).toBe(signs[3]);
    // Adjacent rotors oppose
    for (let i = 0; i < 4; i++) {
      expect(signs[i]).toBe(-signs[(i + 1) % 4]);
    }
    // Named groups exist as expected
    for (let i = 0; i < 4; i++) {
      expect(d.rotors[i].name).toBe(`rotor-${i}`);
      expect(d.rotors[i].children.length).toBe(2); // two blade boxes
    }
  });

  it('velocity (0,0,2) pitches nose down to clamped -0.4 with zero roll', () => {
    const d = buildDrone();
    updateDrone(d, 0.01, { x: 0, y: 0, z: 2 });

    expect(d.body.rotation.x).toBeCloseTo(-0.4, 9);
    expect(d.body.rotation.z).toBeCloseTo(0, 9);
  });

  it('rotor tips stay at horizontal distance armLen regardless of bank', () => {
    for (const armLen of [2, 3.5]) {
      const d = buildDrone({ armLen });
      // Aggressive bank via large velocities (both clamped to +-0.4)
      updateDrone(d, 0.1, { x: 10, y: 0, z: -10 });
      d.root.updateMatrixWorld(true);

      for (let i = 0; i < 4; i++) {
        expect(horizontalDistance(d.rotors[i])).toBeCloseTo(armLen, 6);
        // Blade tips (rotor children) orbit their hub but the hub itself holds position
        expect(d.rotors[i].parent.name).toBe(`arm-${i}`);
      }
    }
  });
});

